Set-Location -LiteralPath 'G:\.gitClones\chatbot\'

if (Test-Path -LiteralPath '.\.venv\Scripts\Activate.ps1') {
    Write-Host 'Activating virtual environment...'
    & '.\.venv\Scripts\Activate.ps1'
}
else {
    Write-Host 'Virtual environment not found. Creating it...'
    py -m venv .venv

    if (Test-Path -LiteralPath '.\.venv\Scripts\Activate.ps1') {
        & '.\.venv\Scripts\Activate.ps1'

        if (Test-Path -LiteralPath '.\requirements.txt') {
            Write-Host 'Installing requirements...'
            python -m pip install -r requirements.txt
        }
    }
    else {
        Write-Host 'Failed to create virtual environment.'
        exit 1
    }
}

if (Test-Path -LiteralPath '.\bot.py') {
    Write-Host 'Starting chatbot...'
    python bot.py
}
else {
    Write-Host 'ERROR: bot.py was not found in G:\.gitClones\chatbot'
}
